/** OpenSearch service. A managed OpenSearch cluster on the OpenSearch operator, with dedicated cluster-manager, data and optional coordinating node pools and operator-generated transport and HTTP TLS. */
export interface SearchServicesData {
  /** The region the service is billed in. */
  location: string;
  /** The service's own settings. */
  properties?: {
    /** The cluster whose namespace holds the search service. */
    clusterId: string;
    /** Number of coordinating-only nodes — nodes that hold no data and no cluster state and exist to fan a search out and merge the results. Zero is the default and is right until a query pattern makes one data node the bottleneck for every search. They are sized by the same preset as the data nodes. */
    coordinatingNodes: number;
    /** Number of data nodes. This is the capacity axis: total raw capacity is this count times the disk size below, before replicas. Every data node also carries the ingest role, so an indexing pipeline needs no separate pool. */
    dataNodes: number;
    /** Number of dedicated cluster-manager nodes. They hold the cluster state in a quorum, so three is the smallest count that survives losing one. One is offered for development and has no quorum at all. An even count is worse than the odd count below it and the API cannot say so — see the service's own documentation. */
    masterNodes: number;
    /** What the platform scrapes. */
    monitoring?: {
      /** Whether the operator is asked for a ServiceMonitor. On by default — docs/plan/12: "a managed service the tenant cannot see the health of is a black box they will not trust with production". ⚠ The metrics themselves come from the prometheus-exporter plugin, which the operator installs into every node on the first reconcile after this is turned on — so turning it on restarts the pods and turning it off does not remove the plugin. */
      enabled?: boolean;
    };
    /** CPU and memory per data node and per coordinating node, either by preset or explicitly. The cluster-manager nodes are sized by the platform and are not affected. */
    sizing?: {
      /** Explicit vCPU quantity in Kubernetes form, for example 500m or 2. Empty means take it from the preset. */
      cpu?: string;
      /** Explicit memory quantity in Kubernetes form, for example 8Gi. Empty means take it from the preset. */
      memory?: string;
      /** A sizing preset from docs/plan/12. Search nodes use the m1 family, which is 1 vCPU to 8 GiB, because OpenSearch is bound by heap and by the filesystem cache rather than by CPU. The m1 rungs below m1.small are deliberately not offered: OpenSearch derives its JVM heap from the container limit and a node under 4 GiB fails a bootstrap check after passing its readiness probe. */
      preset?: SearchServicesPreset;
    };
    /** The data volume, per data node. */
    storage?: {
      /** StorageClass name for every node pool. Empty means the cluster default. */
      class?: string;
      /** Disk size per data node, in Kubernetes quantity form. Grows online; never shrinks. The cluster-manager and coordinating nodes get a fixed 10Gi that is not configurable and is counted against the storage quota anyway. */
      size: string;
    };
    /** OpenSearch version. ⚠ OpenSearch is a fork of Elasticsearch 7.10 (ADR-011 — Elasticsearch is SSPL and is not available to us) and the two have diverged since, so an Elasticsearch 8 client is not promised anything here. Upgrades between the values below are online and in the maintenance window; a third value is a new api-version. */
    version: SearchServicesVersion;
  };
  /** Key/value tags, at most 50 pairs — docs/plan/06 § Tags, locks. Values are strings; the cap applies to the merged set, so a PATCH that adds one tag to a full bag is refused. */
  tags?: Record<string, string>;
}

